import { ChangeDetectorRef, Component, inject, OnInit, signal } from '@angular/core';
import { FormGroup, ReactiveFormsModule, FormControl, NonNullableFormBuilder } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { FormFieldsComponent } from '../../../../shared/components/forms/form-fields/form-fields';
import { SanitizeInput } from '../../../../shared/directives/sanitize-input';
import { commonFormValidator } from '../../../../shared/validators/common-form-validator';
import { LoginUser } from '../../../../shared/interfaces/auth';
import { Auth } from '../../../../core/services/auth';
import { LoadingButton } from '../../../../shared/components/buttons/loading-button/loading-button';
import { RouterLink } from '@angular/router';
import { MatSnackBar, MatSnackBarModule } from '@angular/material/snack-bar';
import { PasswordField } from '../../../../shared/components/forms/password-field/password-field';
import { FormValidation } from '../../../../shared/services/form-validation';
import { ScrollToInvalid } from '../../../../shared/directives/scroll-to-invalid';
import { Redirect } from '../../../../shared/services/redirect';

@Component({
  selector: 'app-login',
  imports: [
    ReactiveFormsModule,
    CommonModule,
    FormFieldsComponent,
    SanitizeInput,
    LoadingButton,
    MatSnackBarModule,
    RouterLink,
    PasswordField,
    ScrollToInvalid,
  ],
  templateUrl: './login.html',
  styleUrl: './login.scss',
})
export class Login implements OnInit {

  private authService = inject(Auth);
  private formBuilder = inject(NonNullableFormBuilder);
  private snackBar = inject(MatSnackBar);
  private formValidation = inject(FormValidation);
  private redirect = inject(Redirect);

  loginForm!: FormGroup<{
    username: FormControl<string>;
    password: FormControl<string>;
  }>;
  isSubmitting = signal(false);
  hasClickedSubmit = false;

  ngOnInit(): void {
    this.createForm();
  }

  createForm() {
    this.loginForm = this.formBuilder.group({
      username: [
        '',
        [
          commonFormValidator({
            required: true,
          }),
        ],
      ],
      password: [
        '',
        [
          commonFormValidator({
            required: true,
          }),
        ],
      ],
    });
  }

  onSubmit(): void {
    this.hasClickedSubmit = true;
    this.formValidation.validateAndRun(this.loginForm, () => {
      this.isSubmitting.set(true);
      this.loginUser();
    });
  }

  loginUser() {
    if (this.loginForm.valid) {
      const controls = this.loginForm.controls;
      const loginData: LoginUser = {
        username: controls.username.value,
        password: controls.password.value,
      };
      this.authService.login(loginData).subscribe({
        next: (response) => {
          console.log('Login successful', response);
          this.redirect.postLogin();
        },
        error: (error) => {
          this.isSubmitting.set(false);
          const message = error.error?.message || 'Login failed. Please try again.';
          this.snackBar.open(message, '✖', { duration: 5000, panelClass: 'snackbar-error' });
          console.error('Login error', error);
        },
      });
    }
  }
}
